<p>诸子百家的思想影响了此后两千多年的中国。比如儒家思想后来成为中国古代的正统思想；到南宋时，出生在福建尤溪的朱熹大半生在福建著书讲学（武夷山的武夷精舍就是他讲学的地方），发展了儒学，他的学派也被称为“闽学”。</p>
