          ref: '（1）主父偃；推恩令。诸侯王把封地分给子弟建立侯国，王国越分越小，表面上是施恩，实际上分割了王国，所以不用强行削地也会逐渐削弱。<br>（2）董仲舒；儒家思想逐渐成为正统思想。<br>（3）经济：统一铸造五铢钱（或盐铁官营）；军事：派卫青、霍去病北击匈奴。<br>（4）加强了中央集权，巩固了大一统局面（西汉进入鼎盛时期）。',
