          title: '材料',
          html: `<p>材料一：</p><div class="source">愿陛下令诸侯得推恩分子弟，以地侯之。彼人人喜得所愿，上以德施，实分其国，不削而稍弱矣。<span class="from">——《史记·平津侯主父列传》</span></div>
<p>材料二：</p><div class="source">诸不在六艺之科孔子之术者，皆绝其道，勿使并进。<span class="from">——《汉书·董仲舒传》</span></div>`
