          prompt: `<p>有人说：“秦始皇开创了大一统，汉武帝巩固了大一统。”</p>
<p>请从<b>政治、思想、经济、军事</b>四个方面，说明汉武帝是怎样巩固大一统的，并对汉武帝作出简要评价（150 字左右）。</p>`,
          write: true,
          sample: `<p><b>政治</b>：颁布推恩令，让诸侯王把封地分给子弟，王国越分越小，解决了王国问题；设刺史监察地方。</p>
<p><b>思想</b>：采纳董仲舒的建议，“罢黜百家，尊崇儒术”，兴办太学，儒家思想逐渐成为正统思想。</p>
<p><b>经济</b>：收回铸币权，统一铸造五铢钱，实行盐铁官营，改善了国家财政。</p>
<p><b>军事</b>：派卫青、霍去病北击匈奴，控制河西走廊，解除了匈奴对北部边境的威胁。</p>
<p><b>评价</b>：这些措施巩固了大一统，使西汉进入鼎盛时期；但他连年征战、大兴土木，加重了百姓负担。应一分为二地看待。</p>`,
