        {
          h: '黄巾起义与东汉衰亡',
          html: `<p>东汉末年，政治黑暗，加上连年灾荒，百姓走投无路。<b>张角</b>利用他创立的<b>太平道</b>传教，秘密组织群众，经过十几年准备，在 <b>184 年</b>发动起义。起义者头扎黄巾，史称<b>黄巾起义</b>。他们提出：</p>
<div class="source">苍天已死，黄天当立，岁在甲子，天下大吉。<span class="from">——《后汉书·皇甫嵩传》</span></div>
<p>“苍天”指东汉政权，“黄天”指起义者要建立的新政权；184 年是甲子年。</p>
<table class="tbl"><tr><th></th><th>陈胜吴广起义</th><th>黄巾起义</th></tr>
<tr><td>时间</td><td>前209 年（秦末）</td><td>184 年（东汉末）</td></tr>
<tr><td>领导人</td><td>陈胜、吴广</td><td>张角</td></tr>
<tr><td>特点</td><td>中国历史上第一次大规模农民起义</td><td>利用宗教（太平道）组织发动，有计划、有准备</td></tr>
<tr><td>结果</td><td>失败，但沉重打击秦朝统治，秦朝不久灭亡</td><td>被镇压，但沉重打击东汉统治，东汉名存实亡</td></tr></table>
<p>为了镇压起义，东汉朝廷让地方官员和豪强自己招兵。起义被镇压后，这些地方势力拥兵自重，互相混战，东汉朝廷名存实亡，中国走向分裂。<b>220 年</b>，曹丕称帝，东汉灭亡。</p>
<div class="key">黄巾起义沉重打击了东汉的统治；此后地方割据势力形成，东汉名存实亡，220 年灭亡。</div>`
        }
