          write: true,
          sample: `<p><b>陈胜吴广起义</b>：前209 年，陈胜、吴广领导，在大泽乡爆发。原因是秦朝暴政。它是中国历史上第一次大规模的农民起义，沉重打击了秦朝统治，秦朝在前207 年灭亡。</p>
<p><b>黄巾起义</b>：184 年，张角领导。原因是东汉外戚宦官交替专权、政治黑暗，加上灾荒。特点是利用太平道组织群众，有计划、有准备。它沉重打击了东汉统治，东汉从此名存实亡，220 年灭亡。</p>
<p><b>共同点和教训</b>：两次起义都是因为统治者残暴或腐败、百姓无法生活而爆发的，都沉重打击了当时的王朝。统治者必须关注民生、清明政治，否则就会失去民心、走向灭亡。</p>`,
